add("work_atc", en, hu)

# locadd only merges: drop the old tutorial texts (work_atc.tut.*) and training keys no longer used here
for lang in ("en", "hu"):
    path = os.path.join(LOC, "locales", lang, "work_atc.json")
    cur = json.load(open(path, encoding="utf-8"))
    cur = {k: v for k, v in cur.items()
           if not k.startswith("work_atc.tut.") and not (k.startswith("work_atc.trn.") and k not in en)}
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(dict(sorted(cur.items())), f, ensure_ascii=False, indent=2)
        f.write("\n")
